import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  pgEnum,
  pgTable,
  serial,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { PICKUP_STATUSES } from "../lib/pickup";
import { user } from "./auth-schema";

// Better Auth's tables (generated by its CLI): users, sessions, accounts, sign-in codes,
// rate limiting. Re-exported so drizzle-kit and the Better Auth adapter see them.
export * from "./auth-schema";

export const bookingStatus = pgEnum("booking_status", [
  // No longer used: before customer accounts, the e-mail was checked here with a code.
  // Kept in the enum because Postgres cannot drop an enum value in place.
  "pending_verification",
  // E-mail verified, spot held while the customer pays.
  "pending_payment",
  "confirmed",
  "cancelled",
]);

export const pickupStatus = pgEnum("pickup_status", PICKUP_STATUSES);

// Online through Stripe, or at the front desk for a customer who comes without booking.
export const paymentMethod = pgEnum("payment_method", ["online", "on_site"]);

export const promoKind = pgEnum("promo_kind", ["percent", "amount"]);

/** Promo codes typed by customers when booking online, created in the manager's space. */
export const promoCodes = pgTable(
  "promo_codes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Stored uppercase: "BIENVENUE10"
    code: text("code").notNull().unique(),
    kind: promoKind("kind").notNull(),
    // 1–100 for a percentage, in cents for an amount
    value: integer("value").notNull(),
    validFrom: timestamp("valid_from", { withTimezone: true }),
    validUntil: timestamp("valid_until", { withTimezone: true }),
    // Null: unlimited. Counted from the bookings that use the code, not a counter.
    maxUses: integer("max_uses"),
    active: boolean("active").notNull().default(true),
    // What the code is for, e.g. "Vacances de la Toussaint"
    description: text("description"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("promo_value_range", sql`${t.value} > 0 AND (${t.kind} = 'amount' OR ${t.value} <= 100)`),
  ],
);

export const parkings = pgTable("parkings", {
  id: serial("id").primaryKey(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  airport: text("airport").notNull(),
  address: text("address").notNull(),
  capacity: integer("capacity").notNull(),
  dailyRateCents: integer("daily_rate_cents").notNull(),
  terminals: text("terminals").array().notNull(),
});

export const bookings = pgTable(
  "bookings",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    reference: text("reference").notNull().unique(),
    // Secret part of the customer's link: /reservation/<accessToken>
    accessToken: text("access_token").notNull().unique(),
    parkingId: integer("parking_id")
      .notNull()
      .references(() => parkings.id),
    // The customer's account (online bookings). Null for a customer registered at the
    // desk, and for bookings made before accounts existed.
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    customerName: text("customer_name").notNull(),
    // Always set online (it is verified); optional for a customer registered at the desk.
    email: text("email"),
    phone: text("phone").notNull(),
    plate: text("plate").notNull(),
    passengers: integer("passengers").notNull(),
    dropoffAt: timestamp("dropoff_at", { withTimezone: true }).notNull(),
    // Planned landing time of the return flight
    returnAt: timestamp("return_at", { withTimezone: true }).notNull(),
    returnTerminal: text("return_terminal"),
    // What the customer pays; the promo discount is kept for the receipt and the e-mails.
    priceCents: integer("price_cents").notNull(),
    discountCents: integer("discount_cents").notNull().default(0),
    promoCodeId: uuid("promo_code_id").references(() => promoCodes.id),
    status: bookingStatus("status").notNull(),
    // When the spot started being held for payment
    heldAt: timestamp("held_at", { withTimezone: true }),
    // Recorded by the front desk when the customer leaves the car (QR code scanned).
    parkedAt: timestamp("parked_at", { withTimezone: true }),
    parkingSpot: text("parking_spot"),
    pickupStatus: pickupStatus("pickup_status").notNull().default("scheduled"),
    bagsReadyAt: timestamp("bags_ready_at", { withTimezone: true }),
    // How many times "J'ai mes bagages" was pressed (each one alerts every driver):
    // capped, so a link cannot press and cancel forever.
    pickupRequests: integer("pickup_requests").notNull().default(0),
    enRouteAt: timestamp("en_route_at", { withTimezone: true }),
    pickedUpAt: timestamp("picked_up_at", { withTimezone: true }),
    paymentMethod: paymentMethod("payment_method").notNull().default("online"),
    stripeSessionId: text("stripe_session_id").unique(),
    paidAt: timestamp("paid_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("bookings_parking_period_idx").on(t.parkingId, t.dropoffAt, t.returnAt),
    index("bookings_return_idx").on(t.returnAt),
    // "Mon espace": a customer's bookings.
    index("bookings_user_idx").on(t.userId),
    index("bookings_dropoff_idx").on(t.dropoffAt),
    // One car per spot: among the cars on site, a spot can only appear once per parking.
    uniqueIndex("bookings_spot_on_site_idx")
      .on(t.parkingId, t.parkingSpot)
      .where(sql`status = 'confirmed' AND parked_at IS NOT NULL AND pickup_status <> 'picked_up'`),
  ],
);

/** One review per booking, left once the customer has been picked up. */
export const reviews = pgTable(
  "reviews",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    bookingId: uuid("booking_id")
      .notNull()
      .unique()
      .references(() => bookings.id, { onDelete: "cascade" }),
    rating: integer("rating").notNull(),
    comment: text("comment"),
    // Only shown on the public site when the customer agreed to it.
    publishConsent: boolean("publish_consent").notNull().default(false),
    // "Sarah M.": first name and initial, never the full name.
    authorName: text("author_name").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("reviews_rating_range", sql`${t.rating} BETWEEN 1 AND 5`),
    index("reviews_published_idx").on(t.publishConsent, t.createdAt),
  ],
);

/** Shuttle team devices that accepted push notifications (one row per browser). */
export const pushSubscriptions = pgTable("push_subscriptions", {
  id: uuid("id").primaryKey().defaultRandom(),
  // The team member who turned them on: a device only receives while that account still
  // opens the shuttle space, and goes with the account. Null for devices registered
  // before this column: they receive nothing until turned on again.
  userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
  // The push service URL identifies the device; re-subscribing updates the keys.
  endpoint: text("endpoint").notNull().unique(),
  p256dh: text("p256dh").notNull(),
  auth: text("auth").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type Parking = typeof parkings.$inferSelect;
export type PromoCode = typeof promoCodes.$inferSelect;
export type Booking = typeof bookings.$inferSelect;
export type Review = typeof reviews.$inferSelect;
